import{_ as s,o as t,c as i,l as a,t as n,N as o}from"./chunks/framework.Bbd9fWQx.js";const y=JSON.parse('{"title":"git-shell | x-cmd man (git man1) | Restricted login shell for Git-only SSH access","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-shell - Restricted login shell for Git-only SSH access","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-shell | x-cmd man (git man1) | Restricted login shell for Git-only SSH access"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-shell - Restricted login shell for Git-only SSH access"}]]},"headers":[],"params":{"isMan":true,"man":"git-shell","category":"git man1","desc":"Restricted login shell for Git-only SSH access"},"relativePath":"git/man1/git-shell.md","filePath":"git/man1/git-shell.md"}'),l={name:"git/man1/git-shell.md"},r={class:"visually-hidden"},h=o(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-shell - Restricted login shell for Git-only SSH access</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chsh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">command</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git-shell</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">@localhost:/path/to/repo.git</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">@localhost</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>This is a login shell for SSH accounts to provide restricted Git access. It permits execution only of server-side Git commands implementing the pull/push functionality, plus custom commands present in a subdirectory named <strong>git-shell-commands</strong> in the user&#39;s home directory.</p><h2 id="commands" tabindex="-1">COMMANDS <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;COMMANDS&quot;">​</a></h2><p><em>git shell</em> accepts the following commands after the <strong>-c</strong> option:</p><p><em>git receive-pack &lt;argument&gt;</em>, <em>git upload-pack &lt;argument&gt;</em>, <em>git upload-archive &lt;argument&gt;</em></p><blockquote><p>Call the corresponding server-side command to support the client&#39;s <em>git push</em>, <em>git fetch</em>, or <em>git archive --remote</em> request.</p></blockquote><p><em>cvs server</em></p><blockquote><p>Imitate a CVS server. See <strong>git-cvsserver</strong>(1).</p></blockquote><p>If a <strong>~/git-shell-commands</strong> directory is present, <em>git shell</em> will also handle other, custom commands by running &quot;<strong>git-shell-commands/&lt;command&gt; &lt;arguments&gt;</strong>&quot; from the user&#39;s home directory.</p><h2 id="interactive-use" tabindex="-1">INTERACTIVE USE <a class="header-anchor" href="#interactive-use" aria-label="Permalink to &quot;INTERACTIVE USE&quot;">​</a></h2><p>By default, the commands above can be executed only with the <strong>-c</strong> option; the shell is not interactive.</p><p>If a <strong>~/git-shell-commands</strong> directory is present, <em>git shell</em> can also be run interactively (with no arguments). If a <strong>help</strong> command is present in the <strong>git-shell-commands</strong> directory, it is run to provide the user with an overview of allowed actions. Then a &quot;git&gt; &quot; prompt is presented at which one can enter any of the commands from the <strong>git-shell-commands</strong> directory, or <strong>exit</strong> to close the connection.</p><p>Generally this mode is used as an administrative interface to allow users to list repositories they have access to, create, delete, or rename repositories, or change repository descriptions and permissions.</p><p>If a <strong>no-interactive-login</strong> command exists, then it is run and the interactive shell is aborted.</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p>To disable interactive logins, displaying a greeting instead:</p><blockquote><pre><code>$ chsh -s /usr/bin/git-shell
$ mkdir $HOME/git-shell-commands
$ cat &gt;$HOME/git-shell-commands/no-interactive-login &lt;&lt;\\EOF
#!/bin/sh
printf &#39;%s\\n&#39; &quot;Hi $USER! You&#39;ve successfully authenticated, but I do not&quot;
printf &#39;%s\\n&#39; &quot;provide interactive shell access.&quot;
exit 128
EOF
$ chmod +x $HOME/git-shell-commands/no-interactive-login
</code></pre></blockquote><p>To enable git-cvsserver access (which should generally have the <strong>no-interactive-login</strong> example above as a prerequisite, as creating the git-shell-commands directory allows interactive logins):</p><blockquote><pre><code>$ cat &gt;$HOME/git-shell-commands/cvs &lt;&lt;\\EOF
if ! test $# = 1 &amp;&amp; test &quot;$1&quot; = &quot;server&quot;
then
        echo &gt;&amp;2 &quot;git-cvsserver only handles \\&quot;server\\&quot;&quot;
        exit 1
fi
exec git cvsserver server
EOF
$ chmod +x $HOME/git-shell-commands/cvs
</code></pre></blockquote><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p>ssh(1), <strong>git-daemon</strong>(1), contrib/git-shell-commands/README</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,27);function c(e,p,g,d,m,u){return t(),i("div",null,[a("h1",r,n(e.$params.man),1),h])}const E=s(l,[["render",c]]);export{y as __pageData,E as default};
